moustache.css:
html[data-theme=dark].bgaext_bright .mf_item,
html[data-theme=dark].bgaext_bright .mf_log_card > div {
  filter: var(--ext-bright);
}
html[data-theme="dark"].bgaext_dark.darkpanel #player_boards .player-board.mf_zone_team_1 {
  background-color: #2f040f !important;
}
html[data-theme="dark"].bgaext_dark.darkpanel #player_boards .player-board.mf_zone_team_2 {
  background-color: #0b1928 !important;
}
html[data-theme=dark].bgaext_dark body {
  background: #fff;
}
html[data-theme=dark].bgaext_dark body:before {
  filter: invert() hue-rotate(180deg);
  opacity: 0.9;
}
html[data-theme=dark].bgaext_dark .mf_zone_team_1 {
  background-color: #2f040f;
}
html[data-theme=dark].bgaext_dark .mf_zone_team_2 {
  background-color: #0b1928;
}
html[data-theme=dark].bgaext_dark .mf_help {
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .mf_zone_result_title {
  background-color: var(--dark-back);
}

zenso.css:
html[data-theme=dark].bgaext_bright .mf_item_back,
html[data-theme=dark].bgaext_bright .mf_item_front,
html[data-theme=dark].bgaext_bright .mf_log_card > div,
html[data-theme=dark].bgaext_bright .mf_panel_icon > div {
  filter: var(--ext-bright);
}
html[data-theme=dark].bgaext_dark body:before {
  filter: invert() hue-rotate(180deg);
}
html[data-theme=dark].bgaext_dark .mf_label > div {
  background-color: var(--dark-10);
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .mf_scoring_container {
  background-color: var(--dark-back);
}
html[data-theme=dark].bgaext_dark .mf_scoring_header {
  border-color: #785457;
}
html[data-theme=dark].bgaext_dark .mf_scoring {
  color: #ab878a;
}
html[data-theme=dark].bgaext_dark .mf_scoring_header_hand {
  color: var(--light-60);
}
